import * as ecs from "@8thwall/ecs";

import { gameData } from "../core/game-data";
import { GameState } from "../core/game-state";


// --------------------------------------------------
// Arcade Truck Driving System
//
// Features:
// - Smooth acceleration
// - Smooth reverse
// - Friction / coasting
// - Smooth steering
// - Heading based movement
// - Works with trucks facing corrected orientation
// --------------------------------------------------


ecs.registerComponent({

  name: "driving",


  schema: {

    acceleration: ecs.f32,

    maxSpeed: ecs.f32,

    reverseSpeed: ecs.f32,

    friction: ecs.f32,

    steeringSpeed: ecs.f32,

  },


  schemaDefaults: {

    // speed gained per second
    acceleration: 0.35,


    // maximum forward speed
    maxSpeed: 0.8,


    // slower reverse speed
    reverseSpeed: 0.25,


    // coasting resistance
    friction: 0.94,


    // radians per second
    steeringSpeed: 1.5,

  },


  tick: (world, component) => {


    const eid = component.eid;


    //---------------------------------------
    // Only active truck drives
    //---------------------------------------

    if(gameData.state !== GameState.DRIVING)
      return;


    if(gameData.truckEid !== eid)
      return;



    const delta =
      Math.min(world.time.delta,0.05);



    const {

      acceleration,

      maxSpeed,

      reverseSpeed,

      friction,

      steeringSpeed,

    } = component.schema;



    const throttle =
      gameData.input.throttle;


    const steering =
      gameData.input.steering;



    //---------------------------------------
    // Steering
    //---------------------------------------

    if(Math.abs(steering)>0.01)
    {

      const speedFactor =
        Math.max(
          0.25,
          Math.abs(gameData.truckSpeed) / maxSpeed
        );


      gameData.truckHeading +=
        steering *
        steeringSpeed *
        speedFactor *
        delta;

    }



    //---------------------------------------
    // Acceleration / Reverse
    //---------------------------------------

    if(throttle !== 0)
    {

      gameData.truckSpeed +=
        throttle *
        acceleration *
        delta;

    }
    else
    {

      // natural slowdown

      gameData.truckSpeed *= friction;

    }



    //---------------------------------------
    // Speed limits
    //---------------------------------------

    gameData.truckSpeed =
      Math.max(
        -reverseSpeed,

        Math.min(
          maxSpeed,
          gameData.truckSpeed
        )
      );



    //---------------------------------------
    // Apply rotation
    //---------------------------------------
    //
    // Truck model correction:
    // If model front/back is flipped,
    // adjust this offset.
    //---------------------------------------


    const visualRotationOffset =
      Math.PI;



    const rotation =
      ecs.math.quat.yRadians(
        gameData.truckHeading +
        visualRotationOffset
      );



    world.transform.setWorldRotation(
      eid,
      rotation
    );



    //---------------------------------------
    // Move using heading vector
    //---------------------------------------

    if(Math.abs(gameData.truckSpeed)>0.001)
    {


      const forwardX =
        Math.sin(
          gameData.truckHeading
        );


      const forwardZ =
        Math.cos(
          gameData.truckHeading
        );



      world.transform.translateWorld(

        eid,

        {

          x:
            forwardX *
            gameData.truckSpeed *
            delta,


          y:0,


          z:
            forwardZ *
            gameData.truckSpeed *
            delta,

        }

      );

    }


  },


});
